import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Ensure amount is non-zero to test the transfer(amount) vs transfer(0) difference
        vm.assume(amount > 0 && amount <= address(c).balance);
        // Set the caller as owner (msg.sender == owner in constructor)
        address owner = address(this);
        uint256 balanceBefore = receiver.balance;
        // Call sendTo
        c.sendTo(receiver, amount);
        uint256 balanceAfter = receiver.balance;
        // Assert that the receiver's balance increased by exactly amount
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

